import{_ as l,a0 as p,w as s,s as i,I as a,x as e,a1 as o,A as r,ao as u}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"促使项目团队作出改变的五步计划 | LCTT x X-CMD","titleTemplate":false,"description":"促使项目团队作出改变的五步计划 | LCTT (201710) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"促使项目团队作出改变的五步计划 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"促使项目团队作出改变的五步计划 | LCTT (201710) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201710/20170126 A 5-step plan to encourage your team to make changes on your project","title":"促使项目团队作出改变的五步计划","tag":"201710","desc":""},"relativePath":"201710/20170126 A 5-step plan to encourage your team to make changes on your project.md","filePath":"[post].md"}'),d={name:"201710/20170126 A 5-step plan to encourage your team to make changes on your project.md"};function m(f,t,g,T,h,C){const n=p("Link");return s(),i("div",null,[t[19]||(t[19]=a("h1",{id:"促使项目团队作出改变的五步计划",tabindex:"-1"},[e("促使项目团队作出改变的五步计划 "),a("a",{class:"header-anchor",href:"#促使项目团队作出改变的五步计划","aria-label":"Permalink to “促使项目团队作出改变的五步计划”"},"​")],-1)),t[20]||(t[20]=a("p",null,[a("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/business/BIZ_Maze2.png?itok=egeRn990",alt:"促使项目团队作出改变的五步计划",title:"五步的计划促使项目团队作出改变"})],-1)),t[21]||(t[21]=a("p",null,"目的是任何团队组建的首要之事。如果一个人足以实现那个目的，那么就没有必要组成团队。而且如果没有重要目标，你根本不需要一个团队。但只要任务需要的专业知识比一个人所拥有的更多，我们就会遇到集体参与的问题——如果处理不当，会使你脱离正轨。",-1)),t[22]||(t[22]=a("p",null,"想象一群人困在洞穴中。没有一个人具备如何出去的全部知识，所以每个人要协作，心路常开，在想要做的事情上尽力配合。当（且仅当）组建了适当的工作团队之后，才能为实现团队的共同目标创造出合适的环境。",-1)),t[23]||(t[23]=a("p",null,"但确实有人觉得待在洞穴中很舒适而且只想待在那里。在组织里，领导者们如何掌控那些实际上抵触改善、待在洞穴中觉得舒适的人？同时该如何找到拥有共同目标但是不在自己组织的人？",-1)),a("p",null,[t[1]||(t[1]=e("我从事指导国际销售培训，刚开始甚至很少有人认为我的工作有价值。所以，我想出一套使他们信服的战术。那个战术非常成功以至于我决定深入研究它并与各位",-1)),o(n,{href:"http://www.slideshare.net/RonMcFarland1/creating-change-58994683"},{default:r(()=>[...t[0]||(t[0]=[e("分享",-1)])]),_:1}),t[2]||(t[2]=e("。",-1))]),t[24]||(t[24]=a("h3",{id:"获得支持",tabindex:"-1"},[e("获得支持 "),a("a",{class:"header-anchor",href:"#获得支持","aria-label":"Permalink to “获得支持”"},"​")],-1)),t[25]||(t[25]=a("p",null,"为了建立公司强大的企业文化，有人会反对改变，并且从幕后打压任何改变的提议。他们希望每个人都待在那个舒适的洞穴里。例如，当我第一次接触到海外销售培训，我受到了一些关键人物的严厉阻挠。他们迫使其他人相信某个东京人做不了销售培训——只要基本的产品培训就行了。",-1)),a("p",null,[t[4]||(t[4]=e("尽管我最终解决了这个问题，但我那时候真的不知道该怎么办。所以，我开始研究顾问们在改变公司里抗拒改变的人的想法这个问题上该如何给出建议。从学者 ",-1)),o(n,{href:"http://www.laurencehaughton.com/"},{default:r(()=>[...t[3]||(t[3]=[e("Laurence Haughton",-1)])]),_:1}),t[5]||(t[5]=e(" 的研究中，我发现一般对于改变的提议，组织中 83% 的人最开始不会支持你。大约 17% _会_从一开始就支持你，但是只要看到一个实验案例成功之后，他们觉得这个主意安全可行了，60% 的人会支持你。最后，有部分人会反对任何改变，无论它有多棒。",-1))]),t[26]||(t[26]=u('<p>我研究的步骤：</p><ul><li>从试验项目开始</li><li>开导洞穴人</li><li>快速跟进</li><li>开导洞穴首领</li><li>全局展开</li></ul><h3 id="_1、-从试验项目开始" tabindex="-1">1、 从试验项目开始 <a class="header-anchor" href="#_1、-从试验项目开始" aria-label="Permalink to “1、 从试验项目开始”">​</a></h3><p>找到高价值且成功率较高的项目——而不是大的、成本高的、周期长的、全局的行动。然后，找到能看到项目价值、理解它的价值并能为之奋斗的关键人物。这些人不应该只是“老好人”或者“朋友”；他们必须相信项目的目标而且拥有推进项目的能力或经验。不要急于求成。只要足够支持你研究并保持进度即可。</p><p>个人而言，我在新加坡的一个小型车辆代理商那里举办了自己的第一场销售研讨会。虽然并不是特别成功，但足以让人们开始讨论销售训练会达到怎样的效果。那时候的我困在洞穴里（那是一份我不想做的工作）。这个试验销售训练是我走出困境的蓝图。</p><h3 id="_2、-开导洞穴人" tabindex="-1">2、 开导洞穴人 <a class="header-anchor" href="#_2、-开导洞穴人" aria-label="Permalink to “2、 开导洞穴人”">​</a></h3><p>洞穴（CAVE）实际上是我从 Laurence Haughton 那里听来的缩略词。它代表着 Citizens Against Virtually Everything。（LCTT 译注，此处一语双关前文提及的洞穴。）</p><p>你得辨别这些人，因为他们会暗地里阻挠项目的进展，特别是早期脆弱的时候。他们容易黑化：总是消极。他们频繁使用“但是”、“如果”和“为什么”，只是想推脱你。他们询问轻易不可得的细节信息。他们花费过多的时间在问题上，而不是寻找解决方案。他们认为每个失败都是一个趋势。他们总是对人而不是对事。他们作出反对建议的陈述却又不能简单确认。</p><p>避开洞穴人；不要让他们太早加入项目的讨论。他们固守成见，因为他们看不到改变所具有的价值。他们安居于洞穴，所以试着让他们去做些其他事。你应该找出我上面提到那 17% 的人群中的关键人物，那些想要改变的人，并且跟他们开一个非常隐秘的准备会。</p><p>我在五十铃汽车（股东之一是通用汽车公司）的时候，销售训练项目开始于一个销往世界上其他小国家的合资分销商，主要是非洲、南亚、拉丁美洲和中东。我的个人团队由通用汽车公司雪佛兰的人、五十铃产品经理和分公司的销售计划员工组成。隔绝其他任何人于这个圈子之外。</p><h3 id="_3、-快速跟进" tabindex="-1">3、 快速跟进 <a class="header-anchor" href="#_3、-快速跟进" aria-label="Permalink to “3、 快速跟进”">​</a></h3><p>洞穴人总是慢吞吞的，那么你就迅速行动起来。如果你在他们参与之前就有了小成就的经历，他们对你团队产生消极影响的能力将大大减弱——你要在他们提出之前就解决他们必然反对的问题。再一次，选择一个成功率高的试验项目，很快能出结果的。然后宣传成功，就像广告上的加粗标题。</p><p>当我在新加坡研讨会上所言开始流传时，其他地区开始意识到销售训练的好处。仅在新加坡研讨会之后，我就被派到马来西亚开展了四次以上。</p><h3 id="_4、-开导洞穴首领" tabindex="-1">4、 开导洞穴首领 <a class="header-anchor" href="#_4、-开导洞穴首领" aria-label="Permalink to “4、 开导洞穴首领”">​</a></h3><p>只要你取得了第一个小项目的成功，就针对能影响洞穴首领的关键人物推荐项目。让团队继续该项目以告诉关键人物成功的经历。一线人员甚至顾客也能提供有力的证明。 洞穴管理者往往只着眼于销量和收益，那么就宣扬项目在降低开支、减少浪费和增加销量方面的价值。</p><p>自新加坡的第一次研讨会及之后，我向直接掌握了五十铃销售渠道的前线销售部门员工和通用汽车真正想看到进展的人极力宣传他们的成功。当他们接受了之后，他们会向上级提出培训请求并让其看到分公司销量的提升。</p><h3 id="_5、-全局展开" tabindex="-1">5、 全局展开 <a class="header-anchor" href="#_5、-全局展开" aria-label="Permalink to “5、 全局展开”">​</a></h3><p>一旦一把手站在了自己这边，立马向整个组织宣告成功的试验项目。讨论项目的扩展。</p><p>用上面的方法，在 21 年的职业生涯中，我在世界各地超过 60 个国家举办了研讨会。我确实走出了洞穴——并且真的看到了广阔的世界。</p><p>（题图：opensource.com）</p><hr><p>作者简介：</p><p>Ron McFarland - Ron McFarland 已在日本工作 40 年，从事国际销售、销售管理和在世界范围内扩展销售业务 30 载有余。他曾去过或就职于 80 多个国家。在过去的 14 年里， Ron 为总部位于东京的日本硬件切割厂在美国和欧洲各地建立分销商。</p><hr>',24)),a("p",null,[t[7]||(t[7]=e("via: ",-1)),o(n,{href:"https://opensource.com/open-organization/17/1/escape-the-cave"},{default:r(()=>[...t[6]||(t[6]=[e("https://opensource.com/open-organization/17/1/escape-the-cave",-1)])]),_:1})]),a("p",null,[t[11]||(t[11]=e("作者：",-1)),o(n,{href:"https://opensource.com/users/ron-mcfarland"},{default:r(()=>[...t[8]||(t[8]=[e("Ron McFarland",-1)])]),_:1}),t[12]||(t[12]=e(" 译者：",-1)),o(n,{href:"https://github.com/XYenChi"},{default:r(()=>[...t[9]||(t[9]=[e("XYenChi",-1)])]),_:1}),t[13]||(t[13]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[10]||(t[10]=[e("wxy",-1)])]),_:1})]),a("p",null,[t[16]||(t[16]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[14]||(t[14]=[e("LCTT",-1)])]),_:1}),t[17]||(t[17]=e(" 原创编译，",-1)),o(n,{href:"https://linux.cn/"},{default:r(()=>[...t[15]||(t[15]=[e("Linux中国",-1)])]),_:1}),t[18]||(t[18]=e(" 荣誉推出",-1))])])}const y=l(d,[["render",m]]);e